import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    vmax = max(a)

    spf = list(range(vmax + 1))
    for p in range(2, int(vmax ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, vmax + 1, p):
                if spf[x] == x:
                    spf[x] = p

    phi = list(range(vmax + 1))
    for p in range(2, vmax + 1):
        if phi[p] == p:
            for x in range(p, vmax + 1, p):
                phi[x] -= phi[x] // p

    # For each d, sums[d] is the sum of 2^(i-1) over prior A_i divisible by d.
    sums = [0] * (vmax + 1)
    answer = 0
    weight = 1
    output = []

    for x in a:
        # Enumerate all divisors of x using its prime factorization.
        divisors = [1]
        y = x
        while y > 1:
            p = spf[y]
            exponent = 0
            while y % p == 0:
                y //= p
                exponent += 1
            old = divisors[:]
            power = 1
            for _ in range(exponent):
                power *= p
                for d in old:
                    divisors.append(d * power)

        # gcd(u, x) = sum_{d | u, d | x} phi(d).
        added = sum(phi[d] * sums[d] for d in divisors) % MOD
        answer = (2 * answer + added) % MOD
        output.append(str(answer))

        for d in divisors:
            value = sums[d] + weight
            sums[d] = value - MOD if value >= MOD else value
        weight = weight * 2 % MOD

    sys.stdout.write('\n'.join(output))

if __name__ == '__main__':
    main()

