import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:]
    limit = max(values)

    # Smallest prime factor for each integer up to the maximum input value.
    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, limit + 1, p):
                if spf[x] == x:
                    spf[x] = p

    # Grundy number for x is the mex of the Grundy numbers of its
    # proper divisors. Process values in increasing order.
    grundy = [0] * (limit + 1)
    for x in range(2, limit + 1):
        t = x
        divisors = [1]
        while t > 1:
            p = spf[t]
            exponent = 0
            while t % p == 0:
                t //= p
                exponent += 1

            previous = divisors
            divisors = []
            power = 1
            for _ in range(exponent + 1):
                divisors.extend(d * power for d in previous)
                power *= p

        reachable = {grundy[d] for d in divisors if d < x}
        mex = 0
        while mex in reachable:
            mex += 1
        grundy[x] = mex

    nim_sum = 0
    for x in values:
        nim_sum ^= grundy[x]
    print('Anna' if nim_sum else 'Bruno')

if __name__ == '__main__':
    main()

