  step=h<<1
  for i in range(0,n,step):
   for j in range(i,i+h):
    x=a[j]; y=a[j+h]
    a[j]=(x+y)%MOD
    a[j+h]=(x-y)%MOD
  h=step

def mul(a,b,m):
 c=[0]*m
 for i,x in enumerate(a):
  if x:
   for j,y in enumerate(b):
    if y:
     k=i+j
     if k>=m:k-=m
     c[k]=(c[k]+x*y)%MOD
 return c

def power(base,e,m):
 r=[0]*m; r[0]=1
 while e:
  if e&1:r=mul(r,base,m)
  e//=2
  if e:base=mul(base,base,m)
 return r

