from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # Group each pair by its larger endpoint. Once the right endpoint r
        # reaches that value, the pair imposes a lower bound on the subarray's
        # left endpoint.
        ending_at = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending_at[b].append((a, idx))

        # The two largest active smaller endpoints determine the normal
        # bound and the bound after removing the strongest pair.
        first = (0, -1)
        second = (0, -1)
        gain = [0] * len(conflictingPairs)
        base = 0

        for right in range(1, n + 1):
            for left_endpoint, idx in ending_at[right]:
                if left_endpoint > first[0]:
                    second = first
                    first = (left_endpoint, idx)
                elif left_endpoint > second[0]:
                    second = (left_endpoint, idx)

            base += right - first[0]
            if first[1] != -1:
                gain[first[1]] += first[0] - second[0]

        return base + max(gain)

