import sys

def main():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())
    edges = []
    for _ in range(M):
        a, b, c = map(int, input().split())
        edges.append((a - 1, b - 1, c))

    queries = []
    closed = [False] * M
    for _ in range(Q):
        z = list(map(int, input().split()))
        if z[0] == 1:
            i = z[1] - 1
            closed[i] = True
            queries.append((1, i))
        else:
            queries.append((2, z[1] - 1, z[2] - 1))

    INF = 10**30
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0
    for i, (a, b, c) in enumerate(edges):
        if not closed[i]:
            dist[a][b] = dist[b][a] = c

    # Distances in the graph after all closures.
    for k in range(N):
        row_k = dist[k]
        for i in range(N):
            dik = dist[i][k]
            if dik == INF:
                continue
            row_i = dist[i]
            for j in range(N):
                candidate = dik + row_k[j]
                if candidate < row_i[j]:
                    row_i[j] = candidate

    answers = []
    # Reverse time: closures become edge insertions.
    for query in reversed(queries):
        if query[0] == 2:
            _, x, y = query
            value = dist[x][y]
            answers.append(str(value if value < INF else -1))
        else:
            _, edge_id = query
            u, v, weight = edges[edge_id]
            # Snapshot distances to the endpoints before inserting the edge.
            du = dist[u][:]
            dv = dist[v][:]
            for i in range(N):
                row_i = dist[i]
                via_u = du[i] + weight
                via_v = dv[i] + weight
                for j in range(N):
                    candidate = min(via_u + dv[j], via_v + du[j])
                    if candidate < row_i[j]:
                        row_i[j] = candidate

    print('\n'.join(reversed(answers)))

if __name__ == '__main__':
    main()

