import sys
import math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    processes = []
    pos = 2
    for _ in range(n):
        a, p, b, q = data[pos:pos + 4]
        pos += 4
        processes.append((a, p, b, q))

    # Any process's output is at most its fastest rate times the number
    # of units bought, and each unit costs at least one yen.
    high = min(budget * max(a, b) for a, p, b, q in processes) + 1

    def feasible(target):
        total_cost = 0
        for a, p, b, q in processes:
            g = math.gcd(a, b)
            if p * b <= q * a:  # S has at least as good cost per output
                # In an optimum, fewer than a/g units of T are needed:
                # replace any such batch by b/g units of S.
                cost = min(
                    y * q + max(0, (target - b * y + a - 1) // a) * p
                    for y in range(a // g)
                )
            else:
                # Symmetrically, enumerate fewer than b/g units of S.
                cost = min(
                    z * p + max(0, (target - a * z + b - 1) // b) * q
                    for z in range(b // g)
                )
            total_cost += cost
            if total_cost > budget:
                return False
        return True

    low = 0
    while low + 1 < high:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

