class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # Pascal triangle for the number of suffixes with a given popcount.
        C = [[0] * (n + 1) for _ in range(n + 1)]
        C[0][0] = 1
        for i in range(1, n + 1):
            C[i][0] = C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        good = [False] * (n + 1)
        for t in range(1, n + 1):
            v = t
            steps = 0
            while v != 1:
                v = v.bit_count()
                steps += 1
            good[t] = steps + 1 <= k

        ans = 0
        prefix_ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = n - i - 1
                for t in range(1, n + 1):
                    need = t - prefix_ones
                    if 0 <= need <= rem:
                        ans += C[rem][need]
                prefix_ones += 1
        return ans % MOD

