class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Binomial coefficients for counting suffixes by their number of 1s.
        choose = [[0] * (n + 1) for _ in range(n + 1)]
        choose[0][0] = 1
        for i in range(1, n + 1):
            choose[i][0] = choose[i][i] = 1
            for j in range(1, i):
                choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD

        # An integer with t set bits takes 1 + steps(t) reductions to reach 1.
        good = [False] * (n + 1)
        for t in range(1, n + 1):
            value = t
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            good[t] = steps + 1 <= k

        # Enumerate numbers less than s by their first bit that differs from s.
        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for total_ones in range(1, n + 1):
                    if good[total_ones]:
                        needed = total_ones - prefix_ones
                        if 0 <= needed <= remaining:
                            answer += choose[remaining][needed]
                prefix_ones += 1

        return answer % MOD

