import sys
from collections import deque

def main():
    input = sys.stdin.readline
    n = int(input())
    graph = [input().strip() for _ in range(n)]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    dist = [[-1] * n for _ in range(n)]
    q = deque()

    # Empty strings are palindromes; single-edge strings are palindromes too.
    for i in range(n):
        dist[i][i] = 0
        q.append((i, i))
    for i in range(n):
        for j, ch in enumerate(graph[i]):
            if ch != '-':
                c = ord(ch) - ord('a')
                outgoing[i][c].append(j)
                incoming[j][c].append(i)
                if dist[i][j] == -1:
                    dist[i][j] = 1
                    q.append((i, j))

    finalized = [[False] * n for _ in range(n)]
    while q:
        u, v = q.popleft()
        if finalized[u][v]:
            continue
        finalized[u][v] = True
        new_dist = dist[u][v] + 2

        # Wrap a palindrome from u to v with matching-label edges x->u and v->y.
        for c in range(26):
            ys = outgoing[v][c]
            if not ys:
                continue
            for x in incoming[u][c]:
                row = dist[x]
                if not any(row[y] == -1 for y in ys):
                    continue
                for y in ys:
                    if not finalized[x][y] and row[y] == -1:
                        row[y] = new_dist
                        q.append((x, y))

    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in dist))

