import sys

class Node:
    __slots__ = ('ch', 'w')
    def __init__(self):
        self.ch = [None, None]
        self.w = 0

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    A = data[1:]
    root = Node()
    # Each mountain condition is a low-bit residue class. Insert it in a
    # trie whose levels are the bits of the shift, least significant first.
    for a in A:
        for t in range(99):
            d = t + 2
            r = ((1 << t) - a) % (1 << d)
            cur = root
            for j in range(d):
                b = (r >> j) & 1
                if cur.ch[b] is None:
                    cur.ch[b] = Node()
                cur = cur.ch[b]
            cur.w += 1

    lo, hi = 1, (1 << 100) - A[-1] - 1
    ans = 0

    def visit(node, depth, residue, score):
        nonlocal ans
        score += node.w
        if depth == 100:
            if lo <= residue <= hi:
                ans = max(ans, score)
            return
        scale = 1 << depth
        for b in (0, 1):
            nr = residue + b * scale
            child = node.ch[b]
            if child is not None:
                visit(child, depth + 1, nr, score)
            else:
                # All completions in this missing subtree have the same score.
                # Check whether at least one such completion lies in [lo, hi].
                lowq = max(0, (lo - nr + (1 << (depth + 1)) - 1) >> (depth + 1))
                highq = (hi - nr) >> (depth + 1)
                if lowq <= highq:
                    ans = max(ans, score)

    visit(root, 0, 0, 0)
    print(ans)

if __name__ == '__main__':
    main()

