import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    m = next(it)
    rows = [0] * n

    for _ in range(m):
        u = next(it) - 1
        v = next(it) - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduce the adjacency matrix over GF(2) to reduced row-echelon form.
    pivots = []
    rank = 0
    for col in range(n):
        pivot_row = next((i for i in range(rank, n) if (rows[i] >> col) & 1), None)
        if pivot_row is None:
            continue
        rows[rank], rows[pivot_row] = rows[pivot_row], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free_cols = [col for col in range(n) if col not in pivot_set]

    # For each free variable, construct a nullspace basis vector. Its bit
    # position in each output value is chosen to be the free column index.
    answer = [0] * n
    for free_col in free_cols:
        vector = 1 << free_col
        for row_index, pivot_col in enumerate(pivots):
            if (rows[row_index] >> free_col) & 1:
                vector |= 1 << pivot_col
        for vertex in range(n):
            if (vector >> vertex) & 1:
                answer[vertex] |= 1 << free_col

    if any(value == 0 for value in answer):
        print("No")
    else:
        print("Yes")
        print(*answer)

