from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Clockwise order in row/column coordinates: NE, SE, SW, NW.
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]

        # straight[d][e][i][j] is the longest alternating 0/2 sequence
        # starting at (i,j), moving in direction d, expecting e (0 or 1=>2).
        straight = [[[[0] * m for _ in range(n)] for _ in range(2)] for _ in range(4)]
        orders = []
        for d, (di, dj) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if di > 0 else range(n)
            orders.append(rows)
            for i in rows:
                for j in range(m):
                    v = grid[i][j]
                    if v not in (0, 2):
                        continue
                    e = 0 if v == 0 else 1
                    ni, nj = i + di, j + dj
                    tail = straight[d][1 - e][ni][nj] if 0 <= ni < n and 0 <= nj < m else 0
                    straight[d][e][i][j] = 1 + tail

        # turned[d][e] permits one clockwise turn at a later step.
        turned = [[[[0] * m for _ in range(n)] for _ in range(2)] for _ in range(4)]
        for d, (di, dj) in enumerate(dirs):
            nd = (d + 1) % 4
            ti, tj = dirs[nd]
            for i in orders[d]:
                for j in range(m):
                    v = grid[i][j]
                    if v not in (0, 2):
                        continue
                    e = 0 if v == 0 else 1
                    ne = 1 - e
                    ni, nj = i + di, j + dj
                    continue_tail = turned[d][ne][ni][nj] if 0 <= ni < n and 0 <= nj < m else 0
                    xi, xj = i + ti, j + tj
                    turn_tail = straight[nd][ne][xi][xj] if 0 <= xi < n and 0 <= xj < m else 0
                    turned[d][e][i][j] = 1 + max(continue_tail, turn_tail)

        answer = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    answer = max(answer, 1)
                    for d, (di, dj) in enumerate(dirs):
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n and 0 <= nj < m:
                            answer = max(answer, 1 + turned[d][1][ni][nj])
        return answer

