from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def count_completions(odds: int, evens: int, next_parity: int) -> int:
            length = odds + evens
            if length == 0:
                return 1
            needed_odds = (length + 1) // 2 if next_parity == 1 else length // 2
            needed_evens = length - needed_odds
            if odds != needed_odds or evens != needed_evens:
                return 0
            return fact[odds] * fact[evens]

        remaining = list(range(1, n + 1))
        result = []
        previous_parity = None

        while remaining:
            selected = None
            for value in remaining:
                parity = value % 2
                if previous_parity is not None and parity == previous_parity:
                    continue

                odds_left = sum(x % 2 for x in remaining if x != value)
                evens_left = len(remaining) - 1 - odds_left
                block_size = count_completions(odds_left, evens_left, 1 - parity)

                if k > block_size:
                    k -= block_size
                else:
                    selected = value
                    break

            if selected is None:
                return []

            result.append(selected)
            remaining.remove(selected)
            previous_parity = selected % 2

        return result

