class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = (powers[i - 1] * 10) % k

        coeff = []
        for i in range(h):
            if i == n - 1 - i:  # center digit in an odd-length palindrome
                coeff.append(powers[i])
            else:
                coeff.append((powers[i] + powers[n - 1 - i]) % k)

        # Bit r in suffix[i] means residue r is achievable by positions i onward.
        suffix = [0] * (h + 1)
        suffix[h] = 1
        for i in range(h - 1, -1, -1):
            prev, c = suffix[i + 1], coeff[i]
            bits = 0
            for r in range(k):
                if (prev >> r) & 1:
                    for d in range(10):
                        bits |= 1 << ((r + d * c) % k)
            suffix[i] = bits

        chosen = []
        residue = 0
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for d in range(9, low - 1, -1):
                need = (-residue - d * c) % k
                if (suffix[i + 1] >> need) & 1:
                    chosen.append(str(d))
                    residue = (residue + d * c) % k
                    break

        half = ''.join(chosen)
        return half + half[:n // 2][::-1]

