    for _ in range(m):
        x, y, z = data[pos] - 1, data[pos + 1] - 1, data[pos + 2]
        pos += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    value = [None] * n
    answer = [0] * n
    for start in range(n):
        if value[start] is not None:
            continue
        value[start] = 0
        queue = [start]
        component = []
        for v in queue:
            component.append(v)
            for w, z in adj[v]:
                expected = value[v] ^ z
                if value[w] is None:
                    value[w] = expected
                    queue.append(w)
                elif value[w] != expected:
                    print(-1)
                    return

        ones = [0] * 31
        for v in component:
            x = value[v]
            for bit in range(31):
                ones[bit] += (x >> bit) & 1

        offset = 0
        size = len(component)
        for bit, count in enumerate(ones):
            if count * 2 > size:
                offset |= 1 << bit
        for v in component:
            answer[v] = value[v] ^ offset

