    t = int(data[0])
    p = 1
    out = []
    for _ in range(t):
        n = int(data[p]); a = data[p+1].decode(); b = data[p+2].decode(); p += 3
        xs = [i for i, c in enumerate(a) if c == '1']
        ys = [i for i, c in enumerate(b) if c == '1']
        m, q = len(xs), len(ys)
        if m < q:
            out.append('-1')
            continue
        # For a proposed displacement bound D, determine if the particles can
        # be partitioned, in order, among all desired occupied squares.
        def feasible(D):
            reach = {0}
            for j, y in enumerate(ys):
                nxt = set()
                left = y - D
                right = y + D
                lo = 0
                while lo < m and xs[lo] < left:
                    lo += 1
                hi = lo
                while hi < m and xs[hi] <= right:
                    hi += 1
                for start in reach:
                    s = max(start + 1, lo)
                    e = hi
                    if j == q - 1:
                        if s <= m <= e:
                            nxt.add(m)
                        continue
                    for end in range(s, e + 1):
                        if end < m:
                            # displacement must not increase from one particle
                            # to the next in their sorted order.
                            if y - xs[end-1] >= ys[j+1] - xs[end]:
                                nxt.add(end)
                reach = nxt
                if not reach:
                    return False
            return m in reach
        low, high = 0, n
        if not feasible(high):
            out.append('-1')
            continue
        while low < high:
            mid = (low + high) // 2
            if feasible(mid):
                high = mid
            else:
                low = mid + 1
        out.append(str(low))
    print('\n'.join(out))

