from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Construct the specified postorder without recursion.
        order = []
        stack = [(0, False)]
        while stack:
            v, visited = stack.pop()
            if visited:
                order.append(v)
            else:
                stack.append((v, True))
                for child in reversed(children[v]):
                    stack.append((child, False))

        postorder = []
        position = [0] * n
        subtree_size = [1] * n
        for i, v in enumerate(order):
            position[v] = i
            postorder.append(s[v])

        # In postorder, every child's size is available before its parent.
        for v in order:
            if parent[v] != -1:
                subtree_size[parent[v]] += subtree_size[v]

        # Manacher radii for odd-length and even-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and postorder[i - k] == postorder[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and postorder[i - k - 1] == postorder[i + k]:
                k += 1
            even[i] = k
