class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        m = len(queries)

        def feasible(k: int) -> bool:
            for i, target in enumerate(nums):
                if target == 0:
                    continue
                bits = 1  # bit s is set iff sum s can be formed
                mask = (1 << (target + 1)) - 1
                for l, r, val in queries[:k]:
                    if l <= i <= r:
                        bits |= bits << val
                        bits &= mask
                        if (bits >> target) & 1:
                            break
                else:
                    return False
            return True

        if feasible(0):
            return 0
        if not feasible(m):
            return -1

        lo, hi = 1, m
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

