import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        if len(str(m)) != digits:
            return -1

        lower = 0 if digits == 1 else 10 ** (digits - 1)
        upper = 10 ** digits - 1

        is_prime = [True] * (upper + 1)
        if upper >= 0:
            is_prime[0] = False
        if upper >= 1:
            is_prime[1] = False
        for p in range(2, int(upper ** 0.5) + 1):
            if is_prime[p]:
                for multiple in range(p * p, upper + 1, p):
                    is_prime[multiple] = False

        if is_prime[n] or is_prime[m]:
            return -1

        # A path's cost includes its initial value and every value reached.
        distances = {n: n}
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != distances.get(value):
                continue
            if value == m:
                return cost

            chars = list(str(value))
            for i, char in enumerate(chars):
                digit = ord(char) - ord('0')
                for changed_digit in (digit - 1, digit + 1):
                    if not 0 <= changed_digit <= 9:
                        continue
                    changed = chars.copy()
                    changed[i] = str(changed_digit)
                    next_value = int(''.join(changed))
                    if next_value < lower or is_prime[next_value]:
                        continue

                    next_cost = cost + next_value
                    if next_cost < distances.get(next_value, float('inf')):
                        distances[next_value] = next_cost
                        heapq.heappush(heap, (next_cost, next_value))

        return -1

