class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        lcp = [None] * n

        # lcp[i][j] is the common-prefix length of nums[i:] and nums[j:]
        for i in range(n - 1, -1, -1):
            row = array('H', [0]) * n
            if i == n - 1:
                for j in range(n):
                    if nums[i] == nums[j]:
                        row[j] = 1
            else:
                nxt = lcp[i + 1]
                for j in range(n - 1):
                    if nums[i] == nums[j]:
                        row[j] = nxt[j + 1] + 1
            lcp[i] = row

        ans = 0
        for i in range(1, n - 1):
            prefix_matches = lcp[0][i] >= i
            for j in range(i + 1, n):
                if (prefix_matches and j >= 2 * i) or lcp[i][j] >= j - i:
                    ans += 1
        return ans

