from typing import List
class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        def zfunc(a):
            m = len(a)
            z = [0] * m
            l = r = 0
            for k in range(1, m):
                if k <= r:
                    z[k] = min(r-k+1, z[k-l])
                while k + z[k] < m and a[z[k]] == a[k+z[k]]:
                    z[k] += 1
                if k + z[k] - 1 > r:
                    l, r = k, k + z[k] - 1
            return z
        z0 = zfunc(nums)
        ans_a = sum(n - 2*i for i in range(1, n) if 2*i < n and z0[i] >= i)
        b = inter = 0
        for i in range(1, n-1):
            z = zfunc(nums[i:])
            good_a = z0[i] >= i
            for d in range(1, n-i):
                if z[d] >= d:
                    b += 1
                    if good_a and d >= i:
                        inter += 1
        return ans_a + b - inter

