import sys

def main():
    data = sys.stdin.buffer.read().split()
    k = int(data[0])
    s, t = data[1], data[2]
    n, m = len(s), len(t)

    if abs(n - m) > k:
        print("No")
        return

    if n == m:
        differences = 0
        for a, b in zip(s, t):
            if a != b:
                differences += 1
                if differences > k:
                    break
        print("Yes" if differences <= k else "No")
        return

    # The lengths differ by one. Check whether the shorter string is a
    # subsequence of the longer string after skipping at most one character.
    if n > m:
        s, t = t, s

    i = j = skipped = 0
    while i < len(s) and j < len(t):
        if s[i] == t[j]:
            i += 1
            j += 1
        else:
            skipped += 1
            j += 1
            if skipped > 1:
                break

    print("Yes" if skipped <= 1 else "No")

if __name__ == "__main__":
    main()

